python.condition.def:
def condition(a, b, op):
  # op: 0:a>b, 1:a<b, 2:a==b, 3:a!=b, 4:a<=b, 5:a>=b
  if op == 0:
    return 1 if a > b else 0
  elif op == 1:
    return 1 if a < b else 0
  elif op == 2:
    return 1 if a == b else 0
  elif op == 3:
    return 1 if a != b else 0
  elif op == 4:
    return 1 if a <= b else 0
  elif op == 5:
    return 1 if a >= b else 0
  return 0

python.print_if.def:
def print_if(cond, msg):
  if cond:
    print(msg)
  return 1 if cond else 0

python.print_matrix.def:
def print_matrix(mat):
  for row in mat:
    print('[ ' + ', '.join(str(x) for x in row) + ' ]')

python.matrix_index.def:
def matrix_index(mat, r, c):
  if r < 0 or c < 0 or r >= len(mat) or c >= len(mat[0]):
    raise IndexError('matrix index out of range')
  return mat[r][c]

python.matrix_add_pointwise.def:
def matrix_add_pointwise(a, b):
  if len(a) != len(b) or (len(a)>0 and len(a[0]) != len(b[0])):
    raise ValueError('matrix sizes must match')
  return [[a[r][c] + b[r][c] for c in range(len(a[0]))] for r in range(len(a))]

python.matrix_sub_pointwise.def:
def matrix_sub_pointwise(a, b):
  if len(a) != len(b) or (len(a)>0 and len(a[0]) != len(b[0])):
    raise ValueError('matrix sizes must match')
  return [[a[r][c] - b[r][c] for c in range(len(a[0]))] for r in range(len(a))]

python.matrix_mul_pointwise.def:
def matrix_mul_pointwise(a, b):
  if len(a) != len(b) or (len(a)>0 and len(a[0]) != len(b[0])):
    raise ValueError('matrix sizes must match')
  return [[a[r][c] * b[r][c] for c in range(len(a[0]))] for r in range(len(a))]

python.matrix_div_pointwise.def:
def matrix_div_pointwise(a, b):
  if len(a) != len(b) or (len(a)>0 and len(a[0]) != len(b[0])):
    raise ValueError('matrix sizes must match')
  res = []
  for r in range(len(a)):
    row = []
    for c in range(len(a[0])):
      row.append(0 if b[r][c] == 0 else a[r][c] / b[r][c])
    res.append(row)
  return res
